// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, description, pixelWidth, pixelHeight}, i) => ({
      image: src, description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: index < 10 ? 3 : index < 20 ? 4 : 5,
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + ' классы',
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + grade + '.pdf',
      answersUrl: 'assets/medvezhonok/' + year + '/' + grade + '-answers.pdf',
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2021, "2-3", [{"author":"Е. Амосов","question":"<em>Заревел тут _____: «Что я, глупенький ребёнок?».</em>\nВставьте вместо прочерка нужное слово.","choices":["<em>медвежонок</em>","<em>поросёнок</em>","<em>аистёнок</em>","<em>индюшонок</em>","<em>лягушонок</em>."],"key":"А","review":["Кто заговорил в стихах","Все названия детёнышей подходят по рифме к слову «ребёнок». Чтобы выбрать одно, обрати внимание на глагол «заревел».","Медведь издаёт рёв. Для остальных животных обычно выбирают другие глаголы, например «квакает» о лягушке. По голосу лучше всего подходит медвежонок, вариант А."]},{"author":"И. Рубанов","question":"Найдите лишнее по смыслу слово.","choices":["<em>квадратный</em>","<em>красный</em>","<em>круглый</em>","<em>прямоугольный</em>","<em>треугольный</em>."],"key":"Б","review":["Признаки предметов","Попробуй нарисовать то, что описывает каждое слово. Квадратный, круглый, прямоугольный и треугольный предметы будут отличаться очертаниями.","Красный цвет можно придать любой из этих фигур. Это слово обозначает цвет, поэтому выделяем вариант Б."]},{"author":"О. Подлесская","question":"Малыш называл животных в книжке: собака <em>—</em> <em>гав-гав</em>, свинья <em>—</em> <em>хрю-хрю</em>, лягушка <em>—</em> <em>ква-ква</em>, зайчик <em>—</em> <em>прыг-прыг</em>, барашек <em>—</em> <em>бе-бе</em>. Какое название малыш придумал не так, как остальные?","choices":["<em>гав-гав</em>","<em>хрю-хрю</em>","<em>ква-ква</em>","<em>прыг-прыг</em>","<em>бе-бе</em>."],"key":"Г","review":["Имена животных у малыша","«Гав-гав», «хрю-хрю», «ква-ква» и «бе-бе» передают звуки, которые издают собака, свинья, лягушка и баран.","«Прыг-прыг» передаёт движение зайчика. Малыш назвал его по прыжкам, поэтому этот ответ стоит отдельно, вариант Г."]},{"author":"Б. Иомдин","question":"Какое слово образовано от названия дерева?","choices":["<em>калина</em>","<em>малина</em>","<em>осина</em>","<em>рябина</em>","<em>дубина.</em>"],"key":"Д","review":["Слово от названия дерева","В названиях «калина», «малина», «осина» и «рябина» одинаковые последние буквы. Проверь, какое слово можно прямо объяснить через название другого растения.","Дубина — толстая палка. Её название образовано от «дуб» с помощью суффикса -ин-. Подходит вариант Д."]},{"author":"Е. Муравенко","question":"Найдите лишнее по смыслу название мебели.","choices":["<em>стул</em>","<em>стол</em>","<em>табуретка</em>","<em>кресло</em>","<em>диван</em>."],"key":"Б","review":["Предметы мебели","На стуле, табуретке, кресле и диване можно сидеть. Эти четыре предмета объединяет их назначение.","На стол обычно ставят или кладут вещи, за ним работают или едят. У него другое назначение, поэтому выбираем вариант Б."]},{"author":"Л. Фёдорова","question":"В каком слове нужно вставить не такую букву, как в остальных?","choices":["<em>ёж_к</em>","<em>ж_раф</em>","<em>ж_ребёнок</em>","<em>ж_вотное</em>","<em>уж_н</em>."],"key":"В","review":["Буквы после ж","Восстанови привычные слова «ёжик», «жираф», «животное» и «ужин». Во всех четырёх после ж нужно написать и, как в правиле «жи пиши с и».","Оставшееся слово — «жеребёнок». После ж в нём стоит е. Это вариант В."]},{"author":"Б. Иомдин","question":"В какой паре оба слова называют одно и то же?","choices":["<em>бараны — баранки</em>","<em>суши — сушки</em>","<em>сельди — селёдки</em>","<em>ложи — ложки</em>","<em>ножи — ножки</em>."],"key":"В","review":["Пары похожих слов","Проверь, можно ли назвать двумя словами одну и ту же вещь. Баранки — выпечка, сушки — сухие колечки, ложки — приборы, ножки — опоры или части тела. Их значения различаются со словами слева.","«Сельди» и «селёдки» обозначают одних и тех же рыб. Второе слово привычнее в разговоре, например на кухне. Подходит вариант В."]},{"author":"О. Подлесская","question":"Что может быть и у яйца, и у ореха?","choices":["желток","листок","скорлупа","ядро","ничего из (А)–(Г)."],"key":"В","review":["Яйцо и орех","Представь, что нужно очистить варёное яйцо и расколоть орех. Снаружи у обоих есть твёрдая защитная оболочка.","Такую оболочку называют скорлупой. Желток есть у яйца, а ядром обычно называют съедобную часть ореха. Общее слово — в варианте В."]},{"author":"Е. Амосов","question":"Какое из слов <strong>не</strong> образовано из двух слов?","choices":["<em>вездеход</em>","<em>дымоход</em>","<em>пароход</em>","<em>переход</em>","<em>теплоход</em>."],"key":"Г","review":["Как собрано слово","Разбери слова по смыслу. Вездеход проходит везде, по дымоходу выходит дым, пароход движется за счёт пара, а название «теплоход» связано с тепловым двигателем.","«Переход» образован от «переходить». Перед корнем ход- здесь есть приставка пере-. Отдельного слова в первой части нет. Ответ Г."]},{"author":"О. Подлесская","question":"<em>Я в _____ на _____.</em>\nКакое слово наиболее вероятно пропущено два раза в этой фразе?","choices":["<em>сапожках</em>","<em>ботиночках</em>","<em>носочках</em>","<em>колготочках</em>","<em>тапочках</em>."],"key":"В","review":["Два предлога, одно слово","«В» в этой фразе может указывать, что надето на ноги, а «на» — какой частью стопы человек опирается. Подбери слово для обеих ситуаций.","«В носочках» значит в паре носков, «на носочках» — на передней части стоп. В двух пропусках подходит одно слово из варианта В."]},{"author":"Е. Муравенко","question":"Как обычно приделывают подошву, пуговицу, значок?","choices":["пришивают, прикалывают, приклеивают","приклеивают, прикалывают, пришивают","приклеивают, пришивают, прикалывают","прикалывают, пришивают, приклеивают","прикалывают, приклеивают, пришивают."],"key":"В","review":["Как крепят предметы","Подошву обычно прикрепляют к обуви клеем. У пуговицы есть отверстия или петля, через которые можно провести нитку.","Пуговицу пришивают, а значок держится на булавке — его прикалывают. Получилось «приклеивают, пришивают, прикалывают», вариант В."]},{"author":"О. Подлесская","question":"Закончите скороговорку: <em>У Кондрата куртка _____.</em>","choices":["<em>грязновата</em>","<em>коротковата</em>","<em>дороговата</em>","<em>странновата</em>","<em>зеленовата</em>."],"key":"Б","review":["Куртка Кондрата","Прочитай вслух «У Кондрата куртка». В этой фразе несколько раз встречаются согласные к, р и т.","Слово «коротковата» повторяет эти звуки. Произнеси несколько раз «У Кондрата куртка коротковата» и услышишь, как они чередуются. Ответ Б."]},{"author":"П. Аркадьев","question":"<em>Мы закусили на _____ руку, и я поднялся, чтобы идти дальше</em> (Д. Н. Мамин-Сибиряк). Как правильно заполнить пропуск?","choices":["<em>длинную</em>","<em>короткую</em>","<em>левую</em>","<em>скорую</em>","<em>спешную</em>."],"key":"Г","review":["Небольшая остановка","Герои ненадолго остановились поесть и снова отправляются в путь. Подбери выражение со значением «быстро, наскоро».","В русском языке есть оборот «на скорую руку». «Закусили на скорую руку» значит быстро перекусили. Выбираем вариант Г."]},{"author":"И. Рубанов","question":"Из какого названия сосуда можно перестановкой букв получить название другого сосуда?","choices":["<em>банка</em>","<em>ведро</em>","<em>колба</em>","<em>лейка</em>","<em>пробирка</em>."],"key":"В","review":["Сосуды из одних букв","Выпиши буквы из слова «колба» по отдельности. Нужно использовать к, о, л, б, а по одному разу и получить другое название сосуда.","Переставь их в порядке б, о, к, а, л. Получится «бокал», ещё одно название сосуда. Выбираем исходное слово «колба», вариант В."]},{"author":"Л. Фёдорова","question":"Незнайка учится сочинять стихи. Он придумал стих, но не знает, как правильно записать некоторые слова. Знайка подсказал, что в четырёх строчках нужно вставить вместо двух пропусков две разные буквы, а в одной строчке <em>—</em> одну и ту же. В какой?","choices":["<em>Рома_ки цвели на лу_ке</em>.","<em>Малы_ки играли в кру_ке</em>.","<em>Лягу_ки дудели в ро_ки</em>.","<em>Оре_ки собрали в ме_ки</em>.","<em>Теле_ки везли пету_ки</em>."],"key":"Г","review":["Стихи с двумя пропусками","Поставь сомнительную согласную перед гласной. Проверочные слова «ромашек», «лужок», «малышек», «кружок», «лягушек», «рожок», «тележек», «петушок» дают разные буквы в каждой паре.","А в «орешки» и «мешки» пишется одна и та же ш. Проверь словами «орешек» и «мешок». Это строка Г."]},{"author":"И. Рубанов","question":"Петя пришёл в гости в двадцать минут седьмого, а Вася — без десяти семь. Кто из них пришёл позже и на сколько минут?","choices":["Петя пришёл позже на 10 минут","Петя и Вася пришли одновременно","Вася пришёл позже на 10 минут","Вася пришёл позже на 20 минут","Вася пришёл позже на 30 минут."],"key":"Д","review":["Когда пришли гости","«Двадцать минут седьмого» означает, что после шести прошло 20 минут. Петя пришёл в 6:20. «Без десяти семь» — до семи осталось 10 минут, то есть Вася пришёл в 6:50.","У обоих время в пределах одного часа. Вычитаем минуты: 50 − 20 = 30. Вася пришёл позже на полчаса, вариант Д."]},{"author":"Е. Амосов","question":"В названии какой головоломки используется меньше всего различных букв?","choices":["<em>кубик Рубика</em>","<em>змейка Рубика</em>","<em>часы Рубика</em>","<em>шар Рубика</em>","<em>пирамидка Рубика</em>."],"key":"А","review":["Буквы в названиях головоломок","Во всех названиях есть «Рубика» с шестью разными буквами — р, у, б, и, к, а. Значит, меньше шести разных букв ни в одном ответе быть не может.","В слове «кубик» все буквы уже входят в этот набор. Каждое другое название добавляет хотя бы одну новую букву. Минимум у «кубика Рубика», вариант А."]},{"author":"Е. Муравенко","question":"В словосочетании <em>м</em><strong><em>иг ра</em></strong><em>дости</em> «спрятано» слово <em>игра</em>. В четырёх из этих пяти словосочетаний «спрятаны» числа, а в одном — нет. В каком?","choices":["<em>артист оперы</em>","<em>цвет рисунка</em>","<em>ряд вагонов</em>","<em>доход инженера</em>","<em>счёты римлян</em>."],"key":"Д","review":["Числа на стыке слов","Соедини несколько букв перед пробелом и после. В «артист оперы» прячется «сто», в «цвет рисунка» — «три», в «ряд вагонов» — «два», в «доход инженера» — «один».","У «счётов римлян» через стык ни одного названия числа не получается. Лишний пример дан в варианте Д."]},{"author":"П. Аркадьев","question":"Какое из данных существительных может быть одушевлённым?","choices":["<em>дырка</em>","<em>норка</em>","<em>пещерка</em>","<em>ямка</em>","ни одно из перечисленных существительных не может быть одушевлённым."],"key":"Б","review":["Существительные на «-ка»","Словом «норка» можно назвать маленькую нору, а можно — пушного зверька. В первом случае оно отвечает на «что?», во втором на «кто?».","Во множественном числе разница тоже видна — «вижу норки» про жилища и «вижу норок» про зверьков. Одушевлённым может быть «норка», вариант Б."]},{"author":"Е. Муравенко","question":"Найдите лишнее по смыслу.","choices":["<em>петушок</em>","<em>гусёнок</em>","<em>щенок</em>","<em>котёнок</em>","<em>ягнёнок</em>."],"key":"А","review":["Названия животных","Гусёнок, щенок, котёнок и ягнёнок — названия детёнышей гуся, собаки, кошки и овцы.","Петушок — ласковое название петуха. Его детёныш называется цыплёнком. По значению лишнее слово в варианте А."]},{"author":"Л. Фёдорова","question":"Миша написал для Васи стишок:\nЗа ворота вышел кот,\nКот по кличке бегемот.\nЕсли прыгнет на ворота,\nРостом будет с бегемота.\n\nВася прочитал и сказал, что в одной строчке есть ошибка. Прав ли Вася?","choices":["Да, ошибка в первой строчке.","Да, ошибка во второй строчке.","Да, ошибка в третьей строчке.","Да, ошибка в четвёртой строчке.","Нет, Вася не прав, ошибки нет ни в одной строчке."],"key":"Б","review":["Кличка кота в стишке","Прочитай две строки, где встречается слово «бегемот». В последней кот сравнивается ростом с животным, поэтому там обычное существительное пишется с маленькой буквы.","Во второй строке это имя кота. Клички пишут с большой буквы — «Кот по кличке Бегемот». Вася нашёл бы ошибку во второй строке, вариант Б."]},{"author":"О. Подлесская","question":"Наконец он придумал ему имя и даже засмеялся от удовольствия.\nИмя получилось такое — Алый.\n— Почему Алый? — удивлялись пограничники. — Он серый весь, даже чёрный.\n— Погодите, погодите, — отвечал Кошкин. — Вот он _____ — сразу поймёте, почему он Алый. (Ю. Коваль. «Алый»)\n\nЧто надо вставить вместо прочерка?","choices":["<em>принесёт палку</em>","<em>громко залает</em>","<em>завиляет хвостом</em>","<em>высунет язык</em>","<em>страшно зарычит</em>."],"key":"Г","review":["Почему пса так назвали","«Алый» значит ярко-красный. Шерсть собаки серая или чёрная, значит, нужно увидеть другую её часть, которая подходит по цвету.","Язык пса яркий и заметный, когда он его высовывает. Так становится понятной кличка Алый. Ответ Г."]},{"author":"И. Рубанов","question":"<em>Мелкий</em>, <em>речной</em>, <em>золотой</em>, _____.\nКаким словом можно продолжить этот список?","choices":["<em>брусничный</em>","<em>клубничный</em>","<em>колбасный</em>","<em>сахарный</em>","<em>яблочный</em>."],"key":"Г","review":["Слово для трёх признаков","Подбери существительное к словам «мелкий», «речной» и «золотой». Мелким бывает песок по размеру зёрен, речным — по месту, золотым — по цвету или составу.","Сахар в виде мелких кристаллов называют «сахарный песок». К общему слову подходит «сахарный» из варианта Г."]},{"author":"Л. Фёдорова","question":"Винни-Пух решил, что по одним гласным буквам иногда можно точно угадать название птицы, и привёл друзьям ряд примеров: 1) <em>_о_о_а</em>; 2) <em>_о_о_е_</em>; 3) <em>_о_у_а_</em> (каждый прочерк стоит вместо одной согласной буквы). Какие из этих примеров не годятся?","choices":["только первый","только второй","только третий","первый и второй","первый и третий."],"key":"Г","review":["Птичьи имена по гласным","Для первого набора подходят и «сорока», и «ворона». Во втором можно восстановить и «воробей», и «соловей». По одним гласным в этих случаях птицу точно не угадаешь.","Третий набор даёт «попугай». Примеры, где нашлось по два разных названия, — первый и второй. Это вариант Г."]},{"author":"О. Подлесская","question":"В детском журнале «Чиж» 1930 года напечатали такую загадку. Разгадайте её и вы!\n\nЗагадка у меня к вам есть,\nЗагадка непростая:\nКакую букву можно есть,\nКогда она пустая?","choices":["З","И","К","О","Р."],"key":"В","review":["Съедобная буква","Назови буквы из вариантов вслух. Буква К называется «ка». Теперь прочитай подряд «ка» и «пуста».","Получилось слово «капуста». Её можно есть, поэтому загадка привела к букве К, вариант В."]},{"author":"С. Переверзева","question":"Маленький Лёва считает, что, когда чего-то ждёшь, ОНО надувается. ОНО — это _____.","choices":["время","спокойствие","безделье","волнение","терпение."],"key":"Д","review":["Что надувается у Лёвы","Вспомни, что говорят, когда человек устал ждать и больше не может ждать спокойно. У него «лопнуло терпение».","Лёва представил, что терпение раздувается от ожидания, как шарик перед тем, как лопнуть. Это вариант Д."]},{"author":"Е. Муравенко","question":"Слова <em>спаниель</em> и <em>апельсин</em> — анаграммы, то есть состоят из одних и тех же букв. А сколько в них одинаковых согласных звуков?","choices":["ни одного","один","два","три","четыре."],"key":"Б","review":["Одинаковые согласные звуки","Сравни согласные по твёрдости. В слове «спаниель» слышатся твёрдые [с] и [п], мягкий [н’]. В слове «апельсин» слышатся мягкие [с’] и [п’], твёрдый [н].","В обоих словах есть одинаковый мягкий [л’]. Других совпадающих согласных нет. Их всего один, вариант Б."]},{"author":"О. Подлесская","question":"Четыре загадки описывают один и тот же предмет, а пятая — другой. Найдите её.","choices":["Одной ручкой — всех встречает,\nДругой ручкой — всех провожает.","Кто приходит,\nКто уходит —\nВсе её за ручку водят.","Ходит, ходит,\nА в избу не заходит.","То назад, то вперёд\nХодит, бродит пароход.\nОстановишь — горе!\nПродырявит море!","У меня знакомых — тьма,\nНе могу их счесть сама,\nПотому что кто пройдёт,\nТот и руку мне пожмёт."],"key":"Г","review":["Предметы в пяти загадках","Ручки и вход в избу подсказывают дверь. Загадки А, Б, В и Д описывают, как дверь открывается, закрывается и как человек берётся за ручку.","В загадке Г предмет ходит взад и вперёд по ткани. Если задержать его на месте, ткань можно прожечь. Этот предмет — утюг, поэтому выделяем вариант Г."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
